  if (r.exit_code !== 0) throw new Error(`Unable to read ${path}: ${r.output}`);
  const desired = r.output
    .replaceAll('960px', '1024px')
    .replaceAll('1280px', '1440px')
    .replace(/md: 960,
(\s*)lg: 1280,/g, 'md: 1024,
$1lg: 1440,');
  const lines = desired.endsWith('
') ? desired.slice(0, -1).split('
') : desired.split('
');
  patch += `*** Delete File: /testbed/${path}
*** Add File: /testbed/${path}
${lines.map((line) => `+${line}`).join('
')}
`;
}
patch += '*** End Patch
